Definition sl_clob : list reg := [10; 11; 12; 13; 14; 15; 16]%bv.
Section FPX_0. Context {fx : PropExec.FPState}.
Definition sl_agree (regs regs' : bvmap 5 word) : Prop := regs_agree (fun r => In r sl_clob) regs regs'.
